import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("Quote: base premiums and insurance values", () => {
    it.todo("should charge only the processing fee for an empty item list — premium 5 G");
    it.todo("should quote a plain sword — base premium 100 G");
    it.todo("should quote a plain amulet — base premium 60 G");
    it.todo("should quote a plain staff — base premium 80 G");
    it.todo("should quote a plain potion — base premium 40 G");
    it.todo("should quote a single rune as a component — base premium 25 G");
    it.todo("should quote a single moonstone as a component — base premium 25 G");
    it.todo("should sum base premiums of several different main items — sword + amulet = 160 G base");
  });

  describe("Quote: component building blocks", () => {
    it.todo("should not apply a block to 2 runes — 50 G base premium");
    it.todo("should apply the block to exactly 3 runes — 60 G base premium");
    it.todo("should not apply a block to 4 runes — 100 G base premium (block requires exactly 3)");
    it.todo("should apply one block plus singles for 7 runes — 175 G base premium");
    it.todo("should not block components of different types — 2 runes + 1 moonstone = 75 G base premium");
    it.todo("should apply two separate blocks — 3 runes + 3 moonstones = 120 G base premium");
  });

  describe("Quote: item-specific modifiers", () => {
    it.todo("should add a 50 % curse surcharge to the cursed item's base premium — cursed sword = 150 G before policy modifiers");
    it.todo("should add a 30 % surcharge for enchantment 5 — sword with enchantment 5 = 130 G before policy modifiers");
    it.todo("should not add a high-enchantment surcharge for enchantment 4 — sword = 100 G before policy modifiers");
    it.todo("should stack curse and high-enchantment surcharges on the same item — cursed sword with enchantment 5 = 180 G before policy modifiers");
    it.todo("should apply the curse surcharge only to the cursed item, not the policy total — cursed sword + plain amulet = 210 G before policy modifiers and fee");
  });

  describe("Quote: policy-wide modifiers", () => {
    it.todo("should apply a 10 % first-insurance surcharge to the policy base premium — sword = 110 G before fee");
    it.todo("should apply a 20 % loyalty discount at exactly 2 years with MHPCO");
    it.todo("should not apply a loyalty discount at 1 year with MHPCO");
    it.todo("should apply a 15 % follow-up discount on the customer's second contract");
    it.todo("should not apply a follow-up discount on the customer's first contract");
    it.todo("should treat every item in a quote as a first insurance regardless of customer history");
    it.todo("should add the 5 G processing fee at the very end");
  });

  describe("Quote: rounding in the MHPCO's favor", () => {
    it.todo("should round a premium of 197.5 G up to 198 G");
    it.todo("should keep intermediate amounts as fractions and round only the final premium");
  });

  describe("Quote: integration examples", () => {
    it.todo("should quote a newcomer's cursed steel sword (enchantment 3, 0 years) — premium 165 G");
    it.todo("should quote a long-standing customer's second contract for a cursed sword (enchantment 7, 3 years) — premium 160 G");
  });

  describe("Quote: errors", () => {
    it.todo("should reject a quote containing an item with an unknown type");
  });

  describe("Claim: standard reimbursement and deductible", () => {
    it.todo("should reimburse a regular sword (steel, enchantment 3) with damage 500 G — payout 400 G");
    it.todo("should reimburse a damaged rune (damage 200 G) — payout 100 G (no enchantment or material clause)");
    it.todo("should apply the 100 G deductible once per damaged item — sword 500 G + amulet 300 G = payout 600 G");
  });

  describe("Claim: special clauses", () => {
    it.todo("should reimburse 50 % for enchantment 9 on a steel sword with damage 1000 G — payout 400 G");
    it.todo("should reimburse 50 % at exactly enchantment 8 on a dragon-material sword with damage 1000 G — payout 400 G");
    it.todo("should fully reimburse a dragon-material sword with enchantment 5 and damage 800 G — payout 700 G");
    it.todo("should let the 50 % rule win over dragon material — dragon sword, enchantment 9, damage 1000 G = payout 400 G");
  });

  describe("Claim: insurance sum and cap", () => {
    it.todo("should cap a policy at twice the insurance sum — sword + amulet = insurance sum 1600 G, cap 3200 G");
    it.todo("should base the cap on unmodified insurance values — cursed sword = cap 2000 G despite premium modifiers");
    it.todo("should count component insurance values in full despite the block discount — sword + 3 runes = insurance sum 1750 G");
    it.todo("should sum insurance values of two swords — insurance sum 2000 G, cap 4000 G");
    it.todo("should exhaust the cap across successive claims — first claim of 1500 G pays 1400 G leaving cap 600 G");
    it.todo("should reduce a later payout to the remaining cap — second claim of 1500 G pays 600 G leaving cap 0 G");
  });

  describe("Claim: rounding in the MHPCO's favor", () => {
    it.todo("should round a payout of 350.5 G down to 350 G");
  });

  describe("Claim: multiple items of the same type", () => {
    it.todo("should treat two sword damage entries as separate damages each with its own deductible");
    it.todo("should reject a claim with more damage entries of a type than the policy covers");
  });

  describe("Claim: errors", () => {
    it.todo("should reject a claim whose damage references an item not covered by the policy");
    it.todo("should reject a claim whose damage references an unknown item type");
    it.todo("should reject a claim containing a damage entry with a negative amount");
  });

  describe("Scenario processing", () => {
    it.todo("should return one result per step in the same order as the input steps");
    it.todo("should let a claim step reference the policy created by an earlier quote step via its zero-based index");
    it.todo("should report a quote result as { premium } and a claim result as { payout, remainingCap }");
  });
});

describe("claim-office CLI", () => {
  it.todo("should read a scenario from stdin and write { results } as JSON to stdout");
  it.todo("should exit with a non-zero status and write an error to stderr for an invalid scenario, writing no results to stdout");
});

