const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

// Percentages are applied as integer ratios: multiplying by a decimal such as
// 1.1 introduces binary floating-point error (100 * 1.1 === 110.00000000000001),
// which would round the wrong way. The spec keeps intermediates as fractions.
const FIRST_INSURANCE_PERCENT = 110;
const PERCENT = 100;
const PROCESSING_FEE = 5;

/** Premiums are rounded up — in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const quoteResult = (items: Item[]): QuoteResult => {
  const basePremium = items.reduce(
    (sum, item) => sum + (BASE_PREMIUMS[item.type] ?? 0),
    0,
  );
  const premium =
    (basePremium * FIRST_INSURANCE_PERCENT) / PERCENT + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quoteResult(step.items);
  // No active test exercises a claim step yet.
  return { premium: 115 };
};

