export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResults {
  results: StepResult[];
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

const HUNDRED = 100;

/**
 * Adds a percentage surcharge as an integer ratio rather than a decimal
 * factor: multiplying by 1.1 introduces binary floating-point error
 * (100 * 1.1 === 110.00000000000001), which would round the wrong way.
 * The spec keeps intermediates as exact fractions and rounds only at the end.
 */
const addPercent = (amount: number, percent: number): number =>
  (amount * (HUNDRED + percent)) / HUNDRED;

/** Premiums are rounded up — in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const basePremiumOf = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) {
    // The spec rejects a quote containing an unknown item type outright, but
    // no active test pins the error behaviour yet. Fail loudly rather than
    // silently pricing an unknown item at zero, which the spec contradicts.
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return basePremium;
};

const quoteResult = (items: Item[]): QuoteResult => {
  const basePremium = items.reduce(
    (sum, item) => sum + basePremiumOf(item),
    0,
  );
  const premium =
    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quoteResult(step.items);
  // No active test exercises a claim step yet. Throwing keeps the gap honest:
  // the previous parked value was a QuoteResult, which the StepResult union
  // accepted silently even though a claim must answer { payout, remainingCap }.
  throw new Error("Claim steps are not implemented yet");
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return { results: scenario.steps.map(runStep) };
};

