const BASE = {sword:100, amulet:60, staff:80, potion:40, rune:25, moonstone:25};
const COMPONENTS = ["rune","moonstone"], SIZE = 3, BLOCK = 60;
const baseOfType = (t,c) => (COMPONENTS.includes(t) && c === SIZE) ? BLOCK : c * BASE[t];
const baseOf = (items) => {
  const m = new Map();
  for (const t of items) m.set(t, (m.get(t) ?? 0) + 1);
  let s = 0;
  for (const [t,c] of m) s += baseOfType(t,c);
  return s;
};
const cases = [
  [["rune","rune"], 50, "2 runes"],
  [["rune","rune","rune"], 60, "3 runes (block)"],
  [["rune","rune","rune","rune"], 100, "4 runes"],
