const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;

const HUNDRED = 100;

/**
 * Adds a percentage surcharge as an integer ratio rather than a decimal
 * factor: multiplying by 1.1 introduces binary floating-point error
 * (100 * 1.1 === 110.00000000000001), which would round the wrong way.
 * The spec keeps intermediates as exact fractions and rounds only at the end.
 */
const addPercent = (amount: number, percent: number): number =>
  (amount * (HUNDRED + percent)) / HUNDRED;

/** Premiums are rounded up — in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const basePremiumOf = (item: Item): number => {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) {
    // The spec rejects a quote containing an unknown item type outright, but
    // no active test pins the error behaviour yet. Fail loudly rather than
    // silently pricing an unknown item at zero, which the spec contradicts.
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return basePremium;
};

/** Component types are sold individually or as a block of alike pieces. */
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/**
 * Base premium for all items of one type. A block rate applies only when a
 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
 */
const basePremiumOfType = (type: string, count: number): number => {
  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
    return COMPONENT_BLOCK_PREMIUM;
  }
  return count * basePremiumOf({ type });
};

const quoteResult = (items: Item[]): QuoteResult => {
  let basePremium = 0;
  for (const [type, count] of countByType(items)) {
    basePremium += basePremiumOfType(type, count);
  }
  const premium =
    addPercent(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;

