node -e '
// Forward check: do the five item-modifier examples stay exact through the
// integer-ratio pipeline once per-item surcharges compose with policy-wide ones?
const HUNDRED = 100;
const addPercent = (a, p) => (a * (HUNDRED + p)) / HUNDRED;
const FEE = 5, FIRST = 10;

// Per-item surcharges apply to the AFFECTED ITEM base; policy-wide to the sum.
const cases = [
  ["cursed sword (100 +50%)",            [addPercent(100, 50)],                150],
  ["sword ench 5 (100 +30%)",            [addPercent(100, 30)],                130],
  ["sword ench 4 (no surcharge)",        [100],                                100],
  ["cursed + ench5 sword (100+50%+30%)", [100 + 50 + 30],                      180],
  ["cursed sword + plain amulet",        [addPercent(100, 50), 60],            210],
];
for (const [label, parts, wantBase] of cases) {
  const base = parts.reduce((a, b) => a + b, 0);
  const premium = addPercent(base, FIRST) + FEE;
  const ok = base === wantBase;
  console.log(ok ? "OK  " : "FAIL", label.padEnd(36), "base", String(base).padStart(5),
    "(want", String(wantBase).padStart(4) + ")",
    " premium", String(Math.ceil(premium)).padStart(4),
    " exact:", Number.isInteger(premium * 100));
}
'

