// Corrected base-relative ADDITIVE model. Recompute the remaining
// item-modifier examples so no stale compounding figures survive.
const FEE = 5, FIRST = 10, CURSE = 50, ENCH = 30, ENCH_MIN = 5;
const BASE = {sword:100, amulet:60, staff:80, potion:40, rune:25, moonstone:25};
const pct = (amt, p) => (amt * p) / 100;

const quote = (items) => {
  let policyBase = 0, surcharges = 0;
  for (const it of items) {
    const b = BASE[it.type];
    policyBase += b;
    if (it.cursed) surcharges += pct(b, CURSE);
    if ((it.ench ?? 0) >= ENCH_MIN) surcharges += pct(b, ENCH);
  }
  const total = policyBase + surcharges + pct(policyBase, FIRST) + FEE;
  return {itemBase: policyBase + surcharges, premium: Math.ceil(total), exact: Number.isInteger(total*100)};
};

const cases = [
  ["ench 5 (THIS CYCLE)",        [{type:"sword", ench:5}],                        130, 145],
  ["ench 4 (no surcharge)",      [{type:"sword", ench:4}],                        100, 115],
  ["cursed + ench5 (stacked)",   [{type:"sword", ench:5, cursed:true}],           180, 195],
  ["cursed sword + plain amulet",[{type:"sword",ench:3,cursed:true},{type:"amulet",ench:2}], 210, 231],
  ["regression cursed sword",    [{type:"sword", ench:3, cursed:true}],           150, 165],
  ["regression plain sword",     [{type:"sword", ench:3}],                        100, 115],
];
for (const [label, items, wantItemBase, wantPremium] of cases) {
  const r = quote(items);
  const ok = r.itemBase === wantItemBase && r.premium === wantPremium;
  console.log(ok?"OK  ":"FAIL", label.padEnd(30), "itemBase", String(r.itemBase).padStart(4),
    "(want", String(wantItemBase).padStart(4)+")", " premium", String(r.premium).padStart(4),
    "(want", String(wantPremium).padStart(4)+")", " exact:", r.exact);
}
'

