// Settled model: every percentage is taken against a BASE and summed (never compounded).
// Item modifiers -> % of that item own base. Policy modifiers -> % of policy base.
const FEE=5, FIRST=10, CURSE=50, ENCH=30, ENCH_MIN=5, LOYAL=20, FOLLOWUP=15, LOYAL_MIN_YEARS=2;
const BASE={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const pct=(a,p)=>(a*p)/100;
const quote=(items,{years=0,contractIndex=0}={})=>{
  let policyBase=0, surch=0;
  for(const it of items){
    const b=BASE[it.type]; policyBase+=b;
    if(it.cursed) surch+=pct(b,CURSE);
    if(it.ench!==undefined && it.ench>=ENCH_MIN) surch+=pct(b,ENCH);
  }
  let policyMods=pct(policyBase,FIRST);
  if(years>=LOYAL_MIN_YEARS) policyMods-=pct(policyBase,LOYAL);
  if(contractIndex>=1)       policyMods-=pct(policyBase,FOLLOWUP);
  const total=policyBase+surch+policyMods+FEE;
  return {itemBase:policyBase+surch, premium:Math.ceil(total), exact:Number.isInteger(total*100)};
};
const cases=[
  ["REMAINING: cursed + ench5",   [{type:"sword",ench:5,cursed:true}], {},                     180,195],
  ["REMAINING: cursed sw + amulet",[{type:"sword",ench:3,cursed:true},{type:"amulet",ench:2}],{},210,231],
  ["INTEGRATION newcomer",        [{type:"sword",ench:3,cursed:true}], {years:0,contractIndex:0},150,165],
  ["INTEGRATION 3yr 2nd contract",[{type:"sword",ench:7,cursed:true}], {years:3,contractIndex:1},180,160],
  ["loyalty exactly 2 years",     [{type:"sword",ench:3}],             {years:2,contractIndex:0},100,105],
  ["no loyalty at 1 year",        [{type:"sword",ench:3}],             {years:1,contractIndex:0},100,115],
];
for(const [label,items,opts,wantBase,wantPrem] of cases){
  const r=quote(items,opts);
  const ok=r.itemBase===wantBase && r.premium===wantPrem;
  console.log(ok?"OK  ":"FAIL",label.padEnd(32),"itemBase",String(r.itemBase).padStart(4),
   "(want",String(wantBase).padStart(4)+")"," premium",String(r.premium).padStart(4),
   "(want",String(wantPrem).padStart(4)+")"," exact:",r.exact);
}
'

