// Settled model, now WITH the follow-up discount keyed to quote-step position.
const FEE=5, FIRST=10, CURSE=50, ENCH=30, ENCH_MIN=5, LOYAL=20, LOYAL_MIN=2, FOLLOW=15;
const BASE={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const pct=(a,p)=>(a*p)/100;
const quote=(items,years,quoteIndex)=>{
  let base=0,surch=0;
  for(const it of items){
    const b=BASE[it.type]; base+=b;
    if(it.cursed) surch+=pct(b,CURSE);
    if(it.ench!==undefined&&it.ench>=ENCH_MIN) surch+=pct(b,ENCH);
  }
  let mods=pct(base,FIRST);
  if(years>=LOYAL_MIN) mods-=pct(base,LOYAL);
  if(quoteIndex>=1)    mods-=pct(base,FOLLOW);
  const total=base+surch+mods+FEE;
  return {premium:Math.ceil(total), exact:Number.isInteger(total*100)};
};
const plain={type:"sword",ench:3};
const cursed7={type:"sword",ench:7,cursed:true};
const rows=[
  ["THIS TEST: 0yr quote#0",      [plain],   0, 0, 115],
  ["THIS TEST: 0yr quote#1",      [plain],   0, 1, 100],
  ["no follow-up on first",       [plain],   0, 0, 115],
  ["INTEGRATION newcomer q#0",    [{type:"sword",ench:3,cursed:true}], 0, 0, 165],
  ["INTEGRATION 3yr q#1 cursed7", [cursed7], 3, 1, 160],
