  const firstInsuranceSurcharge = percentOf(
    policyBase,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  const loyaltyDiscount = isLongStanding(customer)
    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
    : 0;
  const followUpDiscount =
    quoteOrdinal > FIRST_QUOTE_ORDINAL
      ? percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
      : 0;
  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
};

const quoteResult = (
  items: Item[],
  customer: Customer,
  quoteOrdinal: number,
): QuoteResult => {
  const policyBase = policyBaseOf(items);
  const premium =
    policyBase +
    itemSurchargesOf(items) +
    policyModifiersOf(policyBase, customer, quoteOrdinal) +
    PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

const runStep = (
  step: Step,
  customer: Customer,
  quoteOrdinal: number,
): StepResult => {
  if (step.op === "quote") return quoteResult(step.items, customer, quoteOrdinal);
  // No active test exercises a claim step yet. Throwing keeps the gap honest:
  // the previous parked value was a QuoteResult, which the StepResult union
  // accepted silently even though a claim must answer { payout, remainingCap }.
  throw new Error("Claim steps are not implemented yet");
};

export const runScenario = (scenario: Scenario): ScenarioResults => {
  return {
    results: scenario.steps.map((step) => runStep(step, scenario.customer)),
  };
};

