import { runScenario } from "./src/claim-office.js";
const plain = { type: "sword", material: "steel", enchantment: 3, cursed: false };
const cursed3 = { type: "sword", material: "steel", enchantment: 3, cursed: true };
const cursed7 = { type: "sword", material: "steel", enchantment: 7, cursed: true };
const p = (r: unknown) => (r as { premium: number }).premium;

const newcomer = runScenario({
  customer: { yearsWithMHPCO: 0 },
  steps: [{ op: "quote", items: [cursed3] }],
} as never);
console.log("INTEGRATION newcomer cursed sword ->", p(newcomer.results[0]), " (want 165)");

const longStanding = runScenario({
  customer: { yearsWithMHPCO: 3 },
  steps: [
    { op: "quote", items: [plain] },
    { op: "quote", items: [cursed7] },
  ],
} as never);
console.log("INTEGRATION 3yr quote#0 plain     ->", p(longStanding.results[0]), " (want  95)");
console.log("INTEGRATION 3yr quote#1 cursed7   ->", p(longStanding.results[1]), " (want 160)");

const threeQuotes = runScenario({
  customer: { yearsWithMHPCO: 0 },
  steps: [
    { op: "quote", items: [plain] },
    { op: "quote", items: [plain] },
    { op: "quote", items: [plain] },
  ],
} as never);
console.log("third quote also discounted       ->", p(threeQuotes.results[2]), " (want 100)");
EOF
