55	const BASE_PREMIUMS: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
65	const PROCESSING_FEE = 5;
66	
67	const HUNDRED = 100;
68	
69	/**
70	 * The value of a percentage of an amount. Modifiers are summed as separate
71	 * amounts rather than compounded, so each is computed against its own base:
72	 * a cursed sword is 100 + 50 % of 100 + 10 % of 100, not 100 × 1.5 × 1.1.
73	 *
74	 * Multiplies before dividing, keeping the percentage an integer ratio rather
75	 * than a decimal factor: 100 * 1.1 === 110.00000000000001 in binary floating
76	 * point, which would round the wrong way. Intermediates stay exact and only
77	 * the final premium is rounded.
78	 */
79	const percentOf = (amount: number, percent: number): number =>
80	  (amount * percent) / HUNDRED;
81	
82	/** Premiums are rounded up — in the MHPCO's favour. */
83	const roundPremium = (amount: number): number => Math.ceil(amount);
84	
85	const basePremiumOfType = (type: string): number => {
86	  const basePremium = BASE_PREMIUMS[type];
87	  if (basePremium === undefined) {
88	    // The spec rejects a quote containing an unknown item type outright, but
89	    // no active test pins the error behaviour yet. Fail loudly rather than
90	    // silently pricing an unknown item at zero, which the spec contradicts.
91	    throw new Error(`Unknown item type: ${type}`);
92	  }
93	  return basePremium;
94	};
95	
96	/** Component types are sold individually or as a block of alike pieces. */
97	const COMPONENT_TYPES = ["rune", "moonstone"];
98	const COMPONENT_BLOCK_SIZE = 3;
99	const COMPONENT_BLOCK_PREMIUM = 60;
100	
101	const countByType = (items: Item[]): Map<string, number> => {
102	  const counts = new Map<string, number>();
103	  for (const item of items) {
104	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
105	  }
106	  return counts;
107	};
108	
109	/**
110	 * Base premium for a group of alike items. A block rate applies only when a
111	 * component type appears exactly COMPONENT_BLOCK_SIZE times — blocks do not
112	 * repeat, so 4 runes cost 4 singles rather than a block plus a single.
113	 */
114	const basePremiumOfGroup = (type: string, count: number): number => {
115	  if (COMPONENT_TYPES.includes(type) && count === COMPONENT_BLOCK_SIZE) {
116	    return COMPONENT_BLOCK_PREMIUM;
117	  }
118	  return count * basePremiumOfType(type);
119	};
120	
121	const CURSE_SURCHARGE_PERCENT = 50;
122	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
123	const HIGH_ENCHANTMENT_MIN_LEVEL = 5;
124	
125	/**
126	 * Whether an item carries an enchantment at or above the surcharge threshold.
127	 * Components (runes, moonstones) have no enchantment field at all; an absent
128	 * enchantment is not a level of 0, it is the absence of the property, and so
129	 * never qualifies. Stated as an explicit undefined check rather than a numeric
130	 * default so the reason reads as "unenchanted", not "enchanted to zero".
131	 */
132	const isHighlyEnchanted = (item: Item): boolean =>
133	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_MIN_LEVEL;
134	
135	/**
136	 * Item-specific surcharges are a percentage of the affected item's OWN base
137	 * premium, not of the policy total. They are summed alongside the policy-wide
138	 * modifiers rather than compounded with them, so an item that is both cursed
139	 * and highly enchanted carries base + 50 % of base + 30 % of base.
140	 *
141	 * KNOWN GAP: basePremiumOfType gives the item's standalone base, which differs
142	 * from its share of a component block — a rune in a block of 3 is charged 20,
143	 * not 25, so a cursed or highly enchanted rune inside a block would surcharge
144	 * against 25. This affects both surcharge terms, not just the curse. Left as
145	 * is deliberately: the spec defines neither cursed nor enchanted components,
146	 * gives no rule for apportioning a block rate across its pieces, and no test
147	 * pins the behaviour. Resolve it when a test forces a choice, not before.
148	 */
149	const itemSurchargeOf = (item: Item): number => {
150	  const itemBase = basePremiumOfType(item.type);
151	  const curseSurcharge =
152	    item.cursed === true ? percentOf(itemBase, CURSE_SURCHARGE_PERCENT) : 0;
153	  const enchantmentSurcharge = isHighlyEnchanted(item)
154	    ? percentOf(itemBase, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
155	    : 0;
156	  return curseSurcharge + enchantmentSurcharge;
157	};
158	
159	const LOYALTY_DISCOUNT_PERCENT = 20;
160	const LOYALTY_MIN_YEARS = 2;
161	
162	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
163	
164	/**
165	 * Quotes are numbered from this ordinal; every quote after it is a follow-up
166	 * contract. The ordinal counts QUOTE steps only — claim steps interleave with
167	 * quotes in a scenario and must not advance the contract count.
168	 */
169	const FIRST_QUOTE_ORDINAL = 0;
170	
171	/** Long-standing customers qualify from exactly LOYALTY_MIN_YEARS onwards. */
172	const isLongStanding = (customer: Customer): boolean =>
173	  customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS;
174	
175	/** Every contract after the customer's first one in the scenario. */
176	const isFollowUpContract = (quoteOrdinal: number): boolean =>
177	  quoteOrdinal > FIRST_QUOTE_ORDINAL;
178	
179	/** Policy base premium: every group's base, before any modifier. */
180	const policyBaseOf = (items: Item[]): number =>
181	  [...countByType(items)].reduce(
182	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
183	    0,
184	  );
185	
186	const itemSurchargesOf = (items: Item[]): number =>
187	  items.reduce((total, item) => total + itemSurchargeOf(item), 0);
188	
189	/**
190	 * The net of the policy-wide modifiers: surcharges positive, discounts
191	 * negative. Each is a percentage of the POLICY base and they are summed, never
192	 * compounded — a long-standing customer's first insurance is +10 % and -20 % of
193	 * the same base, a net -10 %, not 1.1 × 0.8.
194	 */
195	const policyModifiersOf = (
196	  policyBase: number,
197	  customer: Customer,
198	  quoteOrdinal: number,
199	): number => {
200	  const firstInsuranceSurcharge = percentOf(
201	    policyBase,
202	    FIRST_INSURANCE_SURCHARGE_PERCENT,
203	  );
204	  const loyaltyDiscount = isLongStanding(customer)
205	    ? percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
206	    : 0;
207	  const followUpDiscount = isFollowUpContract(quoteOrdinal)
208	    ? percentOf(policyBase, FOLLOW_UP_DISCOUNT_PERCENT)
209	    : 0;
210	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
211	};
212	
213	const quoteResult = (
214	  items: Item[],
215	  customer: Customer,
216	  quoteOrdinal: number,
217	): QuoteResult => {
218	  const policyBase = policyBaseOf(items);
219	  const premium =
220	    policyBase +
221	    itemSurchargesOf(items) +
222	    policyModifiersOf(policyBase, customer, quoteOrdinal) +
223	    PROCESSING_FEE;
224	  return { premium: roundPremium(premium) };
225	};
