// Find a scenario where rounding an INTERMEDIATE differs from rounding only at the end.
const BASE={sword:100,amulet:60,staff:80,potion:40,rune:25,moonstone:25};
const FEE=5, FIRST=10;
const pct=(a,p)=>(a*p)/100;

const endOnly=(base)=>Math.ceil(base + pct(base,FIRST) + FEE);
// Variant A: round the first-insurance surcharge itself before adding.
const roundSurcharge=(base)=>Math.ceil(base + Math.ceil(pct(base,FIRST)) + FEE);
// Variant B: round the pre-fee subtotal.
const roundSubtotal=(base)=>Math.ceil(Math.ceil(base + pct(base,FIRST)) + FEE);

console.log("base | endOnly | roundSurcharge | roundSubtotal   <- looking for disagreement");
const cands=[];
for(let n=1;n<=9;n++){
  const base=n*25;                       // n runes (no block unless n===3)
  const b = (n===3)?60:base;
  const e=endOnly(b), a=roundSurcharge(b), s=roundSubtotal(b);
  const differs = !(e===a && e===s);
  if(differs) cands.push({n,b,e,a,s});
  console.log(String(n).padStart(2),"runes  base",String(b).padStart(4),"|",String(e).padStart(4),"|",String(a).padStart(4),"|",String(s).padStart(4), differs?"  <-- DIFFERS":"");
}
console.log("");
console.log("candidates where intermediate rounding changes the answer:", JSON.stringify(cands));
'

