const calc=(base, surch, years, ordinal, roundEachTerm)=>{
  const r = roundEachTerm ? Math.ceil : (x)=>x;
  let mods = r(pct(base,FIRST));
  if(years>=2)   mods -= r(pct(base,LOYAL));
  if(ordinal>=1) mods -= r(pct(base,FOLLOW));
  return Math.ceil(base + r(surch) + mods + FEE);
